// Exact-semantics helpers for transpiled VU0 macro-mode library code
// (generated by svr06-recomp/tools/codeaudit/vu0_transpile.py).
// VU float model: inputs with exponent 0xFF are treated as +-FLT_MAX,
// denormals as +-0; results are clamped the same way and flags are set
// like the hardware (MAC Z/S/U/O per lane, STATUS + sticky bits, D/I for Q ops).
#pragma once
#include <cstdint>
#include <cstring>
#include <cmath>
#include <algorithm>

namespace vu0x
{
    inline uint32_t fb(float f) { uint32_t u; std::memcpy(&u, &f, 4); return u; }
    inline float bf(uint32_t u) { float f; std::memcpy(&f, &u, 4); return f; }
    inline float vin(float x)
    {
        const uint32_t u = fb(x), e = (u >> 23) & 0xFFu;
        if (e == 0xFFu) return bf((u & 0x80000000u) | 0x7F7FFFFFu);
        if (e == 0u) return bf(u & 0x80000000u);
        return x;
    }
    inline float vout(float x, int &ou)
    {
        const uint32_t u = fb(x), e = (u >> 23) & 0xFFu;
        if (e == 0xFFu) { ou = 2; return bf((u & 0x80000000u) | 0x7F7FFFFFu); }
        if (e == 0u) { ou = (u & 0x7FFFFFu) ? 1 : 0; return bf(u & 0x80000000u); }
        ou = 0; return x;
    }
    inline float vout(float x) { int ou; return vout(x, ou); }

    inline uint64_t &GL(R5900Context *c, int n) { return reinterpret_cast<uint64_t *>(&c->r[n])[0]; }
    inline uint64_t &GH(R5900Context *c, int n) { return reinterpret_cast<uint64_t *>(&c->r[n])[1]; }
    inline uint64_t sx32(uint64_t v) { return (uint64_t)(int64_t)(int32_t)(uint32_t)v; }
    inline float *VFw(R5900Context *c, int r) { return reinterpret_cast<float *>(&c->vu0_vf[r]); }
    inline void VFr(R5900Context *c, int r, float (&o)[4])
    {
        if (r == 0) { o[0] = 0.0f; o[1] = 0.0f; o[2] = 0.0f; o[3] = 1.0f; return; }
        std::memcpy(o, &c->vu0_vf[r], 16);
    }
    inline float VFlane(R5900Context *c, int r, int i) { float o[4]; VFr(c, r, o); return o[i]; }
    inline float *ACC(R5900Context *c) { return reinterpret_cast<float *>(&c->vu0_acc); }
    inline void vfwrite(R5900Context *c, int r, const float (&v)[4], int dest)
    {
        if (r == 0) return;
        float *d = VFw(c, r);
        for (int i = 0; i < 4; ++i) if (dest & (8 >> i)) d[i] = v[i];
    }
    inline void updateMac(R5900Context *c, const float (&out)[4], const int (&ou)[4], int dest)
    {
        uint32_t m = 0;
        for (int i = 0; i < 4; ++i)
        {
            if (!(dest & (8 >> i))) continue;
            const uint32_t v = fb(out[i]);
            const int bit = 3 - i;
            if ((v & 0x7FFFFFFFu) == 0) m |= 1u << bit;
            if (v & 0x80000000u) m |= 1u << (bit + 4);
            if (ou[i] & 1) m |= 1u << (bit + 8);
            if (ou[i] & 2) m |= 1u << (bit + 12);
        }
        c->vu0_mac_flags = m;
        uint32_t st = 0;
        if (m & 0x000Fu) st |= 1; if (m & 0x00F0u) st |= 2; if (m & 0x0F00u) st |= 4; if (m & 0xF000u) st |= 8;
        c->vu0_status = (uint16_t)((c->vu0_status & 0xFF0u) | st | (st << 6));
    }
    inline void setQFlags(R5900Context *c, bool inv, bool dz)
    {
        uint32_t st = (c->vu0_status & ~0x30u) & 0xFFFu;
        if (inv) st |= 0x10u | 0x400u;
        if (dz) st |= 0x20u | 0x800u;
        c->vu0_status = (uint16_t)st;
    }
    enum Op { ADD, SUB, MUL, MADD, MSUB, MAX, MIN };
    // b[] holds the already-normalised second operand per lane.
    inline void fmac(R5900Context *c, Op op, int fd, int fs, const float (&b)[4], int dest, bool toAcc)
    {
        float a[4]; VFr(c, fs, a);
        for (auto &x : a) x = vin(x);
        float out[4]; int ou[4];
        float *acc = ACC(c);
        for (int i = 0; i < 4; ++i)
        {
            float r;
            switch (op)
            {
            case ADD: r = a[i] + b[i]; break;
            case SUB: r = a[i] - b[i]; break;
            case MUL: r = a[i] * b[i]; break;
            case MADD: { const float p = a[i] * b[i]; const float s = vin(acc[i]); r = s + p; break; }
            case MSUB: { const float p = a[i] * b[i]; const float s = vin(acc[i]); r = s - p; break; }
            case MAX: r = (b[i] > a[i]) ? b[i] : a[i]; break;
            default: r = (b[i] < a[i]) ? b[i] : a[i]; break;
            }
            out[i] = vout(r, ou[i]);
        }
        if (op != MAX && op != MIN) updateMac(c, out, ou, dest);
        if (toAcc) { for (int i = 0; i < 4; ++i) if (dest & (8 >> i)) acc[i] = out[i]; }
        else vfwrite(c, fd, out, dest);
    }
    inline void bcast(R5900Context *c, int ft, int lane, float (&b)[4]) { const float v = vin(VFlane(c, ft, lane)); b[0] = b[1] = b[2] = b[3] = v; }
    inline void bval(float v, float (&b)[4]) { v = vin(v); b[0] = b[1] = b[2] = b[3] = v; }
    inline void vreg(R5900Context *c, int ft, float (&b)[4]) { VFr(c, ft, b); for (auto &x : b) x = vin(x); }

    inline void opmula(R5900Context *c, int fs, int ft)
    {
        float a[4], b[4]; vreg(c, fs, a); vreg(c, ft, b);
        const float x0 = a[1] * b[2], x1 = a[2] * b[0], x2 = a[0] * b[1];
        float out[4] = {0, 0, 0, 0}; int ou[4] = {0, 0, 0, 0};
        out[0] = vout(x0, ou[0]); out[1] = vout(x1, ou[1]); out[2] = vout(x2, ou[2]);
        float *acc = ACC(c); acc[0] = out[0]; acc[1] = out[1]; acc[2] = out[2];
        updateMac(c, out, ou, 0xE);
    }
    inline void opmsub(R5900Context *c, int fd, int fs, int ft)
    {
        float a[4], b[4]; vreg(c, fs, a); vreg(c, ft, b);
        const float x[3] = {a[1] * b[2], a[2] * b[0], a[0] * b[1]};
        float *acc = ACC(c);
        float out[4]; int ou[4] = {0, 0, 0, 0};
        for (int i = 0; i < 3; ++i) { const float s = vin(acc[i]); out[i] = vout(s - x[i], ou[i]); }
        out[3] = (fd == 0) ? 1.0f : VFw(c, fd)[3];
        updateMac(c, out, ou, 0xE);
        vfwrite(c, fd, out, 0xE);
    }
    inline void ftoi(R5900Context *c, int ft, int fs, int sh, int dest)
    {
        float a[4]; vreg(c, fs, a);
        float out[4];
        for (int i = 0; i < 4; ++i)
        {
            double v = (double)a[i] * (double)(1 << sh);
            v = std::max(std::min(v, 2147483647.0), -2147483648.0);
            const int32_t iv = (int32_t)(int64_t)v;
            std::memcpy(&out[i], &iv, 4);
        }
        vfwrite(c, ft, out, dest);
    }
    inline void itof(R5900Context *c, int ft, int fs, int sh, int dest)
    {
        float a[4]; VFr(c, fs, a);
        float out[4];
        for (int i = 0; i < 4; ++i)
        {
            int32_t iv; std::memcpy(&iv, &a[i], 4);
            const float f = (float)iv; const float d = (float)(1 << sh);
            out[i] = vout(f / d);
        }
        vfwrite(c, ft, out, dest);
    }
    inline void vmove(R5900Context *c, int ft, int fs, int dest) { float a[4]; VFr(c, fs, a); vfwrite(c, ft, a, dest); }
    inline void vmr32(R5900Context *c, int ft, int fs, int dest) { float a[4]; VFr(c, fs, a); float o[4] = {a[1], a[2], a[3], a[0]}; vfwrite(c, ft, o, dest); }
    inline void vdiv(R5900Context *c, int fs, int fsf, int ft, int ftf)
    {
        const float n = vin(VFlane(c, fs, fsf)), d = vin(VFlane(c, ft, ftf));
        if (d == 0.0f) { c->vu0_q = bf(((fb(n) ^ fb(d)) & 0x80000000u) | 0x7F7FFFFFu); setQFlags(c, n == 0.0f, n != 0.0f); }
        else { c->vu0_q = vout(n / d); setQFlags(c, false, false); }
    }
    inline void vsqrt(R5900Context *c, int ft, int ftf)
    {
        const float d = vin(VFlane(c, ft, ftf));
        c->vu0_q = vout((float)std::sqrt(std::fabs((double)d)));
        setQFlags(c, (fb(d) >> 31) && d != 0.0f, false);
    }
    inline void vrsqrt(R5900Context *c, int fs, int fsf, int ft, int ftf)
    {
        const float n = vin(VFlane(c, fs, fsf)), d = vin(VFlane(c, ft, ftf));
        if (d == 0.0f) { c->vu0_q = bf((fb(n) & 0x80000000u) | 0x7F7FFFFFu); setQFlags(c, n == 0.0f, n != 0.0f); }
        else { const float s = (float)std::sqrt(std::fabs((double)d)); c->vu0_q = vout(n / s); setQFlags(c, (fb(d) >> 31) != 0, false); }
    }
    // PS2 FPU (COP1) single precision: same clamping model, no IEEE specials.
    inline float fpr(R5900Context *c, int r) { return c->f[r]; }
    inline void fpw(R5900Context *c, int r, float v) { c->f[r] = v; }
    inline float fpuop(int op, float a, float b)
    {
        a = vin(a); b = vin(b);
        switch (op)
        {
        case 0: return vout(a + b);
        case 1: return vout(a - b);
        case 2: return vout(a * b);
        default:
            if (b == 0.0f) return bf(((fb(a) ^ fb(b)) & 0x80000000u) | 0x7F7FFFFFu);
            return vout(a / b);
        }
    }
    inline uint32_t ctlRead(R5900Context *c, int r)
    {
        if (r < 16) return c->vi[r];
        if (r == 16) return c->vu0_status;
        if (r == 17) return c->vu0_mac_flags;
        if (r == 18) return c->vu0_clip_flags;
        if (r == 21) return fb(c->vu0_i);
        if (r == 22) return fb(c->vu0_q);
        return 0;
    }
    inline void ctlWrite(R5900Context *c, int r, uint32_t v)
    {
        if (r > 0 && r < 16) c->vi[r] = (uint16_t)v;
        else if (r == 16) c->vu0_status = (uint16_t)((c->vu0_status & 0x3Fu) | (v & 0xFC0u));
        else if (r == 18) c->vu0_clip_flags = v & 0xFFFFFFu;
        else if (r == 21) c->vu0_i = bf(v);
        else if (r == 22) c->vu0_q = bf(v);
    }
    // Guest memory access (uses the runtime's getMemPtr/getConstMemPtr).
    inline uint32_t ld32(uint8_t *ram, uint32_t a) { const uint8_t *p = getConstMemPtr(ram, a); uint32_t v = 0; if (p) std::memcpy(&v, p, 4); return v; }
    inline void st32(uint8_t *ram, uint32_t a, uint32_t v) { uint8_t *p = getMemPtr(ram, a); if (p) std::memcpy(p, &v, 4); }
    inline uint64_t ld64(uint8_t *ram, uint32_t a) { const uint8_t *p = getConstMemPtr(ram, a & ~7u); uint64_t v = 0; if (p) std::memcpy(&v, p, 8); return v; }
    inline void st64(uint8_t *ram, uint32_t a, uint64_t v) { uint8_t *p = getMemPtr(ram, a & ~7u); if (p) std::memcpy(p, &v, 8); }
    inline void ldq(uint8_t *ram, uint32_t a, uint64_t &lo, uint64_t &hi) { const uint8_t *p = getConstMemPtr(ram, a & ~15u); if (p) { std::memcpy(&lo, p, 8); std::memcpy(&hi, p + 8, 8); } }
    inline void stq(uint8_t *ram, uint32_t a, uint64_t lo, uint64_t hi) { uint8_t *p = getMemPtr(ram, a & ~15u); if (p) { std::memcpy(p, &lo, 8); std::memcpy(p + 8, &hi, 8); } }
    inline void ldvf(uint8_t *ram, uint32_t a, float (&t)[4]) { const uint8_t *p = getConstMemPtr(ram, a & ~15u); if (p) std::memcpy(t, p, 16); else std::memset(t, 0, 16); }
    inline void stvf(uint8_t *ram, uint32_t a, const float (&t)[4]) { uint8_t *p = getMemPtr(ram, a & ~15u); if (p) std::memcpy(p, t, 16); }
}
